/* Switchboard styles: one plain CSS file, no UI library.
   Colors live in variables at the top so the whole theme can be changed in one place. */
:root {
  --ink: #14213d;          /* deep navy: top bar, our reply bubbles */
  --ink-2: #1f2f52;
  --accent: #e76f51;       /* warm coral: main buttons, highlights */
  --accent-dark: #d0583b;
  --accent-soft: #fdebe5;
  --paper: #faf7f2;        /* warm off-white page background */
  --panel: #ffffff;
  --line: #ece6dc;
  --text: #1b1f2a;
  --muted: #7a7f8c;
  --green: #2a9d8f;
  --green-soft: #e3f4f1;
  --sand-soft: #fbf1dc;
  --red: #c8423a;
  --chat-bg: #f3eee6;
  --radius: 14px;
  --shadow: 0 1px 2px rgba(20, 33, 61, .06), 0 4px 14px rgba(20, 33, 61, .05);
}

* { box-sizing: border-box; }
html, body, #root { height: 100%; }
body { margin: 0; font: 14px/1.5 'Manrope', system-ui, sans-serif; color: var(--text); background: var(--paper); -webkit-font-smoothing: antialiased; }
button, input, textarea, select { font: inherit; color: inherit; }
h1, h2, h3 { font-family: 'Fraunces', Georgia, serif; font-weight: 600; letter-spacing: -.01em; }

.muted { color: var(--muted); }
.small { font-size: 12px; }
.loading { height: 100%; display: grid; place-items: center; color: var(--muted); }

/* ---------- buttons ---------- */
.btn { border: 1px solid transparent; border-radius: 10px; padding: 9px 16px; cursor: pointer; font-weight: 700; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; gap: 8px; transition: background .15s, transform .05s, box-shadow .15s; white-space: nowrap; }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { opacity: .4; cursor: not-allowed; }
.btn.primary { background: var(--accent); color: white; box-shadow: 0 2px 0 var(--accent-dark); }
.btn.primary:hover:not(:disabled) { background: var(--accent-dark); }
.btn.ghost { background: var(--panel); border-color: var(--line); }
.btn.ghost:hover:not(:disabled) { border-color: #d8d0c3; background: #fdfbf8; }
.btn.on-dark { background: transparent; border-color: rgba(255,255,255,.22); color: white; }
.btn.on-dark:hover { background: rgba(255,255,255,.08); }
.btn.wide { width: 100%; }
.btn.big { padding: 13px 18px; font-size: 15px; border-radius: 12px; }

/* ---------- avatars and tags ---------- */
.avatar { width: 40px; height: 40px; flex: none; border-radius: 12px; display: inline-flex; align-items: center; justify-content: center; font-weight: 800; font-size: 13px; color: white; }
.avatar.round { border-radius: 50%; }
.avatar.small { width: 30px; height: 30px; font-size: 11px; }

.tag { font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 6px; display: inline-flex; align-items: center; gap: 5px; }
.tag::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.tag.free { background: var(--sand-soft); color: #a26a12; }
.tag.mine { background: var(--green-soft); color: var(--green); }
.tag.taken { background: #e8ecf5; color: var(--ink-2); }
.tag.closed { background: #efedea; color: var(--muted); }

/* ================= LOGIN ================= */
.login-page { min-height: 100%; display: grid; grid-template-columns: 1.1fr 1fr; }
.login-showcase { background: var(--ink); color: white; padding: 48px 56px; display: flex; flex-direction: column; justify-content: space-between; position: relative; overflow: hidden; }
.login-showcase::after { /* soft glow in the corner */
  content: ''; position: absolute; width: 520px; height: 520px; right: -180px; bottom: -200px; border-radius: 50%;
  background: radial-gradient(circle, rgba(231,111,81,.35), transparent 65%);
}
.login-showcase h2 { font-size: 40px; line-height: 1.1; margin: 0 0 14px; max-width: 460px; }
.login-showcase p { color: #b9c1d6; max-width: 420px; margin: 0; font-size: 15px; }

.preview { position: relative; z-index: 1; display: flex; flex-direction: column; gap: 10px; max-width: 380px; margin: 36px 0; }
.preview .b { padding: 10px 14px; border-radius: 14px; font-size: 13px; max-width: 80%; box-shadow: 0 8px 24px rgba(0,0,0,.18); }
.preview .b.in { background: white; color: var(--text); border-bottom-left-radius: 4px; }
.preview .b.out { background: var(--accent); align-self: flex-end; border-bottom-right-radius: 4px; }
.preview .b small { display: block; opacity: .7; font-size: 11px; margin-top: 2px; }
.preview .note-chip { align-self: flex-start; background: #fff4cf; color: #6b5414; font-size: 12px; padding: 7px 12px; border-radius: 10px; font-weight: 600; }

.login-side { display: flex; align-items: center; justify-content: center; padding: 32px; }
.login-card { width: 100%; max-width: 380px; }
.login-card h1 { font-size: 30px; margin: 22px 0 6px; }
.login-card p { margin: 0 0 28px; }
.login-steps { margin: 28px 0 0; padding: 0; list-style: none; display: grid; gap: 12px; color: var(--muted); font-size: 13px; }
.login-steps li { display: flex; gap: 10px; align-items: flex-start; }
.login-steps b { flex: none; width: 22px; height: 22px; border-radius: 50%; background: var(--accent-soft); color: var(--accent-dark); display: grid; place-items: center; font-size: 11px; }

.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 17px; letter-spacing: -.01em; }
.logo { width: 32px; height: 32px; border-radius: 9px; background: var(--accent); position: relative; flex: none; }
.logo::before, .logo::after { /* two little "speech" lines */
  content: ''; position: absolute; left: 8px; height: 3px; border-radius: 2px; background: white;
}
.logo::before { top: 11px; width: 16px; }
.logo::after { top: 18px; width: 10px; }

/* ================= APP LAYOUT ================= */
.app { height: 100%; display: flex; flex-direction: column; }
.topbar { display: flex; align-items: center; gap: 14px; padding: 0 20px; height: 60px; flex: none; background: var(--ink); color: white; }
.topbar .brand { margin-right: 18px; }
.ws-switch { display: flex; align-items: center; gap: 8px; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.12); border-radius: 10px; padding: 4px 6px 4px 12px; }
.ws-switch select { background: transparent; border: 0; color: white; font-weight: 700; outline: none; cursor: pointer; }
.ws-switch select option { color: var(--text); }
.role { font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; padding: 3px 7px; border-radius: 6px; background: rgba(255,255,255,.1); color: #c9d1e6; }
.role.admin { background: rgba(231,111,81,.2); color: #ffb29e; }
.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.me { display: flex; flex-direction: column; line-height: 1.2; text-align: right; }
.me span { font-size: 11px; color: #9aa5c0; }

.inbox { flex: 1; display: flex; min-height: 0; }

/* ---------- conversation list ---------- */
.sidebar { width: 330px; flex: none; background: var(--panel); border-right: 1px solid var(--line); display: flex; flex-direction: column; }
.sidebar-head { padding: 18px 16px 12px; border-bottom: 1px solid var(--line); }
.sidebar-title { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.sidebar-title h3 { margin: 0; font-size: 20px; }
.tabs { display: grid; grid-template-columns: repeat(3, 1fr); background: var(--paper); border: 1px solid var(--line); border-radius: 10px; padding: 3px; }
.tab { border: 0; background: none; padding: 6px 0; border-radius: 7px; cursor: pointer; color: var(--muted); font-weight: 700; font-size: 13px; }
.tab.active { background: var(--panel); color: var(--text); box-shadow: var(--shadow); }

.live { font-size: 12px; font-weight: 700; display: inline-flex; align-items: center; gap: 6px; padding: 3px 9px; border-radius: 999px; }
.live::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.live.on { color: var(--green); background: var(--green-soft); }
.live.on::before { animation: pulse 1.8s ease-in-out infinite; }
.live.off { color: var(--red); background: #fbe9e7; }
@keyframes pulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(42,157,143,.5); } 50% { box-shadow: 0 0 0 5px rgba(42,157,143,0); } }

.conversation-list { overflow-y: auto; flex: 1; padding: 8px; }
.conversation-row { width: 100%; display: flex; gap: 12px; align-items: center; text-align: left; border: 0; background: none; padding: 11px 10px; border-radius: 12px; cursor: pointer; position: relative; transition: background .12s; }
.conversation-row:hover { background: var(--paper); }
.conversation-row.selected { background: var(--accent-soft); }
.conversation-row.selected::before { content: ''; position: absolute; left: 0; top: 12px; bottom: 12px; width: 3px; border-radius: 3px; background: var(--accent); }
.row-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.row-top { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.row-top strong { font-weight: 700; letter-spacing: .01em; }
.row-bottom { display: flex; gap: 6px; flex-wrap: wrap; }
.time { color: var(--muted); font-size: 11px; font-weight: 600; }
.list-empty { padding: 24px 12px; text-align: center; color: var(--muted); font-size: 13px; }

/* ---------- conversation ---------- */
.main { flex: 1; min-width: 0; background: var(--chat-bg); }
.conversation { display: flex; height: 100%; }
.conversation-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.conversation-head { display: flex; align-items: center; gap: 12px; padding: 12px 20px; height: 68px; background: var(--panel); border-bottom: 1px solid var(--line); }
.contact { font-weight: 800; font-size: 15px; }
.actions { margin-left: auto; display: flex; gap: 8px; }

.messages {
  flex: 1; overflow-y: auto; padding: 24px clamp(16px, 4vw, 48px); display: flex; flex-direction: column; gap: 6px;
  /* subtle dotted "paper" pattern behind the chat */
  background-color: var(--chat-bg);
  background-image: radial-gradient(rgba(20,33,61,.07) 1px, transparent 1px);
  background-size: 18px 18px;
}
.day { align-self: center; font-size: 11px; font-weight: 700; color: var(--muted); background: rgba(255,255,255,.8); padding: 3px 10px; border-radius: 999px; margin: 8px 0; }
.bubble-row { display: flex; }
.bubble-row.out { justify-content: flex-end; }
.bubble { max-width: min(560px, 70%); padding: 9px 14px 7px; border-radius: 16px; box-shadow: 0 1px 1px rgba(20,33,61,.08); word-wrap: break-word; }
.bubble-row.in .bubble { background: var(--panel); border-bottom-left-radius: 5px; }
.bubble-row.out .bubble { background: var(--ink); color: white; border-bottom-right-radius: 5px; }
.bubble-meta { font-size: 11px; opacity: .65; margin-top: 3px; display: flex; gap: 8px; justify-content: flex-end; }
.status { font-weight: 700; text-transform: capitalize; }
.status.delivered { color: #7fd8c9; opacity: 1; }
.status.delivered::before { content: '✓✓ '; }
.status.sent::before { content: '✓ '; }
.status.queued::before { content: '◷ '; }
.status.failed { color: #ffb4ab; }
.status.failed::before { content: '! '; }

.error { margin: 0 20px 10px; padding: 9px 14px; border-radius: 10px; background: #fbe9e7; color: var(--red); font-weight: 600; }
.composer { display: flex; gap: 10px; padding: 14px 20px; background: var(--panel); border-top: 1px solid var(--line); }
.composer input { flex: 1; padding: 11px 16px; border: 1px solid var(--line); border-radius: 12px; outline: none; background: var(--paper); transition: border-color .15s, box-shadow .15s, background .15s; }
.composer input:focus, .field:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); background: white; }

.empty { height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 24px; }
.empty h3 { margin: 16px 0 4px; font-size: 22px; }
.empty-art { width: 92px; height: 70px; position: relative; }
.empty-art span { position: absolute; height: 26px; border-radius: 12px; box-shadow: var(--shadow); }
.empty-art span:nth-child(1) { left: 0; top: 0; width: 62px; background: white; }
.empty-art span:nth-child(2) { right: 0; top: 22px; width: 54px; background: var(--ink); }
.empty-art span:nth-child(3) { left: 10px; top: 44px; width: 40px; background: var(--accent); }

/* ---------- notes ---------- */
.notes { width: 300px; flex: none; background: var(--panel); border-left: 1px solid var(--line); display: flex; flex-direction: column; }
.notes-head { padding: 14px 16px; height: 68px; border-bottom: 1px solid var(--line); display: flex; flex-direction: column; justify-content: center; }
.notes-head strong { display: flex; align-items: center; gap: 8px; }
.lock { width: 18px; height: 18px; border-radius: 5px; background: var(--ink); display: inline-grid; place-items: center; color: white; font-size: 10px; }
.unlock, .note-form { padding: 16px; display: flex; flex-direction: column; gap: 10px; }
.unlock { margin: auto 0; }
.unlock-art { width: 48px; height: 48px; border-radius: 14px; background: var(--sand-soft); display: grid; place-items: center; font-size: 22px; margin: 0 auto 4px; }
.field { padding: 10px 12px; border: 1px solid var(--line); border-radius: 10px; outline: none; resize: vertical; background: var(--paper); }
.note-list { flex: 1; overflow-y: auto; padding: 16px; display: flex; flex-direction: column; gap: 10px; }
.note { background: #fff6d8; border-radius: 4px 12px 12px 12px; padding: 11px 12px; white-space: pre-wrap; box-shadow: 0 1px 0 #f0e2b0; }
.note .muted { margin-top: 6px; display: block; }
.note-form { border-top: 1px solid var(--line); }

/* ---------- smaller screens ---------- */
@media (max-width: 1100px) { .notes { display: none; } }
@media (max-width: 860px) {
  .login-page { grid-template-columns: 1fr; }
  .login-showcase { display: none; }
}
@media (max-width: 700px) {
  .sidebar { width: 100%; }
  .inbox:has(.conversation) .sidebar { display: none; }
  .me, .role { display: none; }
}

