.row-top { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.row-top strong { font-weight: 700; letter-spacing: .01em; }
.row-bottom { display: flex; gap: 6px; flex-wrap: wrap; }
.time { color: var(--muted); font-size: 11px; font-weight: 600; }
