.conversation { display: flex; height: 100%; }
.conversation-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.conversation-head { display: flex; align-items: center; gap: 12px; padding: 12px 20px; height: 68px; background: var(--panel); border-bottom: 1px solid var(--line); }
.contact { font-weight: 800; font-size: 15px; }
.actions { margin-left: auto; display: flex; gap: 8px; }

.messages {
