/* Switchboard: one plain CSS file. Colors are variables so they are easy to change. */
:root {
  --bg: #f5f6fa;
  --panel: #ffffff;
  --border: #e6e8ef;
  --text: #1d2130;
  --muted: #6b7185;
  --primary: #4f46e5;
  --primary-soft: #eef0ff;
  --green: #16a34a;
  --green-soft: #e8f7ee;
  --amber-soft: #fff7e0;
  --red: #dc2626;
  --dark: #151827;
  --radius: 12px;
}

* { box-sizing: border-box; }
body { margin: 0; font: 14px/1.45 'Inter', system-ui, -apple-system, sans-serif; color: var(--text); background: var(--bg); }
button, input, textarea, select { font: inherit; }

.muted { color: var(--muted); }
.small { font-size: 12px; }
.loading, .empty { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; color: var(--muted); text-align: center; padding: 24px; }
.empty h3 { margin: 8px 0 4px; color: var(--text); }
.empty-icon { font-size: 40px; }
.empty.small { height: auto; font-size: 13px; }

/* ---------- buttons, badges, avatars ---------- */
.btn { border: 1px solid transparent; border-radius: 8px; padding: 8px 14px; cursor: pointer; font-weight: 600; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; gap: 6px; transition: background .15s, opacity .15s; }
.btn:disabled { opacity: .45; cursor: not-allowed; }
.btn.primary { background: var(--primary); color: white; }
.btn.primary:hover:not(:disabled) { background: #4338ca; }
.btn.ghost { background: white; border-color: var(--border); color: var(--text); }
.btn.ghost:hover:not(:disabled) { background: var(--bg); }
.btn.wide { width: 100%; }

.avatar { width: 36px; height: 36px; flex: none; border-radius: 50%; background: var(--primary-soft); color: var(--primary); display: inline-flex; align-items: center; justify-content: center; font-weight: 700; font-size: 13px; }
.avatar.small { width: 28px; height: 28px; font-size: 11px; }

.pill { font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 999px; }
.pill.free { background: var(--amber-soft); color: #92600a; }
.pill.mine { background: var(--green-soft); color: var(--green); }
.pill.taken { background: var(--primary-soft); color: var(--primary); }
.pill.closed { background: #eceef3; color: var(--muted); }

.role-badge { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; padding: 3px 8px; border-radius: 6px; background: rgba(255,255,255,.12); color: #c7c9ff; }
.role-badge.admin { color: #ffd479; }

/* ---------- login ---------- */
.login-page { min-height: 100vh; display: flex; align-items: center; justify-content: center; padding: 16px; background: radial-gradient(circle at 20% 20%, #6d5efc 0, transparent 45%), radial-gradient(circle at 80% 80%, #22c1c3 0, transparent 40%), var(--dark); }
.login-card { width: 100%; max-width: 420px; background: white; border-radius: 20px; padding: 36px 32px; text-align: center; box-shadow: 0 30px 80px rgba(0,0,0,.35); }
.login-card h1 { margin: 14px 0 6px; font-size: 28px; }
.login-card p { margin: 0 0 24px; }
.features { list-style: none; padding: 0; margin: 24px 0 0; display: grid; gap: 8px; text-align: left; color: var(--muted); }
.logo { width: 30px; height: 30px; border-radius: 8px; background: linear-gradient(135deg, #6d5efc, #22c1c3); color: white; display: inline-flex; align-items: center; justify-content: center; font-weight: 800; }
.logo.big { width: 56px; height: 56px; border-radius: 16px; font-size: 26px; }

/* ---------- layout ---------- */
.app { height: 100vh; display: flex; flex-direction: column; }
.topbar { display: flex; align-items: center; gap: 12px; padding: 10px 18px; background: var(--dark); color: white; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 16px; margin-right: 12px; }
.workspace-select { background: rgba(255,255,255,.1); color: white; border: 1px solid rgba(255,255,255,.2); border-radius: 8px; padding: 6px 10px; }
.workspace-select option { color: var(--text); }
.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 10px; }
.user-name { font-weight: 600; }

.inbox { flex: 1; display: flex; min-height: 0; }

/* ---------- conversation list ---------- */
.sidebar { width: 320px; flex: none; background: var(--panel); border-right: 1px solid var(--border); display: flex; flex-direction: column; }
.sidebar-head { display: flex; align-items: center; justify-content: space-between; padding: 12px; border-bottom: 1px solid var(--border); }
.tabs { display: flex; background: var(--bg); border-radius: 8px; padding: 3px; }
.tab { border: 0; background: none; padding: 5px 12px; border-radius: 6px; cursor: pointer; color: var(--muted); font-weight: 600; }
.tab.active { background: white; color: var(--text); box-shadow: 0 1px 3px rgba(0,0,0,.08); }
.live { font-size: 12px; font-weight: 600; display: flex; align-items: center; gap: 6px; }
.live::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: currentColor; }
.live.on { color: var(--green); }
.live.on::before { animation: pulse 1.6s infinite; }
.live.off { color: var(--red); }
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: .3; } }

.conversation-list { overflow-y: auto; flex: 1; padding: 6px; }
.conversation-row { width: 100%; display: flex; gap: 10px; align-items: center; text-align: left; border: 0; background: none; padding: 10px; border-radius: 10px; cursor: pointer; }
.conversation-row:hover { background: var(--bg); }
.conversation-row.selected { background: var(--primary-soft); }
.row-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.row-top { display: flex; justify-content: space-between; gap: 8px; }
.row-bottom { display: flex; gap: 6px; }
.time { color: var(--muted); font-size: 12px; }

/* ---------- conversation ---------- */
.main { flex: 1; min-width: 0; }
.conversation { display: flex; height: 100%; }
.conversation-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.conversation-head { display: flex; align-items: center; gap: 12px; padding: 12px 18px; background: var(--panel); border-bottom: 1px solid var(--border); }
.contact { font-weight: 700; font-size: 15px; }
.actions { margin-left: auto; display: flex; gap: 8px; }

.messages { flex: 1; overflow-y: auto; padding: 20px; display: flex; flex-direction: column; gap: 8px; }
.bubble-row { display: flex; }
.bubble-row.out { justify-content: flex-end; }
.bubble { max-width: 65%; padding: 9px 13px; border-radius: 14px; box-shadow: 0 1px 2px rgba(0,0,0,.05); }
.bubble-row.in .bubble { background: white; border: 1px solid var(--border); border-bottom-left-radius: 4px; }
.bubble-row.out .bubble { background: var(--primary); color: white; border-bottom-right-radius: 4px; }
.bubble-meta { font-size: 11px; opacity: .75; margin-top: 4px; display: flex; gap: 6px; align-items: center; justify-content: flex-end; }
.status { text-transform: capitalize; font-weight: 600; }
.status.delivered::before { content: '✓✓ '; }
.status.sent::before { content: '✓ '; }
.status.queued::before { content: '⏳ '; }
.status.failed { color: #ffd0d0; }
.status.failed::before { content: '⚠ '; }

.error { margin: 0 18px 8px; padding: 8px 12px; border-radius: 8px; background: #fdecec; color: var(--red); }
.composer { display: flex; gap: 8px; padding: 14px 18px; background: var(--panel); border-top: 1px solid var(--border); }
.composer input { flex: 1; padding: 10px 14px; border: 1px solid var(--border); border-radius: 10px; outline: none; }
.composer input:focus, .unlock input:focus, .note-form textarea:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-soft); }

/* ---------- notes ---------- */
.notes { width: 290px; flex: none; background: #fffdf5; border-left: 1px solid var(--border); display: flex; flex-direction: column; }
.notes-head { padding: 14px; border-bottom: 1px solid var(--border); display: flex; flex-direction: column; gap: 2px; font-weight: 700; }
.unlock, .note-form { padding: 14px; display: flex; flex-direction: column; gap: 8px; }
.unlock input, .note-form textarea { padding: 9px 12px; border: 1px solid var(--border); border-radius: 8px; outline: none; resize: vertical; }
.note-list { flex: 1; overflow-y: auto; padding: 14px; display: flex; flex-direction: column; gap: 8px; }
.note { background: var(--amber-soft); border: 1px solid #f3e2a9; border-radius: 10px; padding: 10px; display: flex; flex-direction: column; gap: 4px; white-space: pre-wrap; }

/* ---------- small screens ---------- */
@media (max-width: 1000px) {
  .notes { display: none; }
}
@media (max-width: 700px) {
  .sidebar { width: 100%; }
  .inbox:has(.conversation) .sidebar { display: none; }
  .user-name, .role-badge { display: none; }
}

