// Small helper around fetch. Every call sends the session cookie.

export type Role = 'admin' | 'agent';

export interface Me {
  sub: string;
  name?: string;
  workspaces: { id: string; role: Role }[];
}

export interface Conversation {
  contact: string;
  assignee: string | null;
  assigneeName?: string | null;
  state: 'open' | 'closed';
  lastActivityAt: string;
}

export interface Message {
  dir: 'in' | 'out';
  id: string;
  text: string;
  at: string;
  status?: string;
}

export interface Note {
  id: string;
  authorName: string;
  ciphertext: string;
  iv: string;
  createdAt: string;
}

export async function api<T>(path: string, options: RequestInit = {}): Promise<{ status: number; body: T }> {
  const res = await fetch(path, {
    credentials: 'include',
    headers: { 'content-type': 'application/json' },
    ...options,
  });
  const body = await res.json().catch(() => ({}));
  return { status: res.status, body: body as T };
}

import { useEffect, useRef, useState } from 'react';

export interface Frame {
  seq?: number;
  type: string;
  contact?: string;
  after?: number;
}

// Opens the WebSocket for one workspace and calls onFrame for every update.
// If the connection drops, it reconnects with ?after=<last seq we saw>,
// so the server re-sends everything we missed.
export function useLiveUpdates(workspace: string, onFrame: (frame: Frame) => void) {
  const [online, setOnline] = useState(false);

  // keep the latest callback without reconnecting every render
  const callback = useRef(onFrame);
  callback.current = onFrame;

  useEffect(() => {
    let lastSeq: number | undefined;
    let socket: WebSocket | undefined;
    let stopped = false;
    let retryDelay = 500;

    function connect() {
      const protocol = location.protocol === 'https:' ? 'wss' : 'ws';
      let url = `${protocol}://${location.host}/ws?workspace=${encodeURIComponent(workspace)}`;
      if (lastSeq !== undefined) url += `&after=${lastSeq}`;
      socket = new WebSocket(url);

      socket.onopen = () => {
        setOnline(true);
        retryDelay = 500;
      };

      socket.onmessage = (event) => {
        const frame = JSON.parse(event.data) as Frame;
        if (frame.type === 'hello') {
          // first connection: start from where the server is now
          if (lastSeq === undefined) lastSeq = frame.after;
          return;
        }
        if (typeof frame.seq === 'number') {
          if (lastSeq !== undefined && frame.seq <= lastSeq) return; // already seen
          lastSeq = frame.seq;
        }
        callback.current(frame);
      };

      socket.onclose = () => {
        setOnline(false);
        if (stopped) return;
        retryDelay = Math.min(retryDelay * 2, 8000); // wait longer each time, max 8 s
        setTimeout(connect, retryDelay);
      };
    }

    connect();
    return () => {
      stopped = true;
      socket?.close();
    };
  }, [workspace]);

  return online;
}

// End-to-end encryption for private notes, using the browser's Web Crypto API.
//
// Agents of a workspace agree on a "team passphrase" outside the app (for
// example told in person). Each browser turns the passphrase into an AES key.
// The passphrase and the key never leave the browser; the server only gets
// the encrypted note. See PROTOCOL.md.

const encoder = new TextEncoder();
const decoder = new TextDecoder();

const toBase64 = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes));
const fromBase64 = (text: string) => Uint8Array.from(atob(text), (c) => c.charCodeAt(0));

// passphrase -> AES-256 key. PBKDF2 makes guessing the passphrase slow.
// The salt is the workspace id, so the same passphrase gives a different key
// in a different workspace.
export async function deriveKey(passphrase: string, workspace: string): Promise<CryptoKey> {
  const baseKey = await crypto.subtle.importKey('raw', encoder.encode(passphrase), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt: encoder.encode('switchboard-notes:' + workspace), iterations: 200_000, hash: 'SHA-256' },
    baseKey,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

export async function encryptNote(key: CryptoKey, text: string) {
  const iv = crypto.getRandomValues(new Uint8Array(12)); // new random iv for every note
  const encrypted = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, encoder.encode(text));
  return { ciphertext: toBase64(new Uint8Array(encrypted)), iv: toBase64(iv) };
}

// Returns null if the key is wrong (AES-GCM detects it).
export async function decryptNote(key: CryptoKey, ciphertext: string, iv: string): Promise<string | null> {
  try {
    const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: fromBase64(iv) }, key, fromBase64(ciphertext));
    return decoder.decode(plain);
  } catch {
    return null;
  }
}

// Every contact gets its own avatar color, always the same one for the same
// phone number (a tiny hash picks from a fixed palette).
const COLORS = ['#e76f51', '#2a9d8f', '#457b9d', '#8a5a83', '#c08a2e', '#3d5a80', '#b5654b', '#4f772d'];

export function avatarColor(key: string) {
  let hash = 0;
  for (const ch of key) hash = (hash * 31 + ch.charCodeAt(0)) % 1000;
  return COLORS[hash % COLORS.length];
}

// "Ben Ortiz" -> "BO", "+14155550101" -> "01"
export function initials(name: string) {
  if (name.startsWith('+')) return name.slice(-2);
  const parts = name.replace(/[^A-Za-z ]/g, ' ').trim().split(/\s+/);
  return ((parts[0]?.[0] ?? '?') + (parts[1]?.[0] ?? '')).toUpperCase();
}
